class Book:
 def __init__(self,path,title):self.c=canvas.Canvas(str(path),pagesize=(W,H));self.c.setTitle(title);self.c.setAuthor('Timeless Empowerment Foundation');self.y=690;self.page=0
 def start(self,title,kicker='60-DAY TOTAL MENTAL MAKEOVER',number=None):
  c=self.c;self.page+=1;c.setFillColor(HexColor('#faf8f1'));c.rect(0,0,W,H,fill=1,stroke=0);c.drawImage(LOGO,48,708,52,52,mask='auto');c.setFillColor(GREEN);c.setFont('Bold',8);c.drawString(115,743,'TIMELESS EMPOWERMENT FOUNDATION');c.setFont('Body',7);c.drawString(115,728,kicker);c.setStrokeColor(GOLD);c.line(48,698,564,698);self.y=681;self.add(title,'title');self.y-=7
  c.setStrokeColor(LINE);c.line(48,55,564,55);c.setFillColor(INK);c.setFont('Body',6.3);c.drawString(48,43,'Published/Owned by Timeless Empowerment Foundation. Created/Designed by Thornton H. Taylor (Board Member).');c.drawString(48,32,'Structure Designed by Supreme Development Group (SDG). English edition 1.0.0. Educational use; not clinical care.');c.setFont('Bold',8);c.drawRightString(564,66,str(number if number is not None else self.page))
 def add(self,text,style='p'):
  p=Paragraph(html.escape(text).replace('\n','<br/>'),styles[style]);ww,hh=p.wrap(516,650);assert self.y-hh>77,(self.page,self.y,hh,text[:60]);p.drawOn(self.c,48,self.y-hh);self.y-=hh+9
 def lines(self,label,n=5):
  self.add(label,'h');c=self.c;c.setStrokeColor(LINE)
  for _ in range(n):self.y-=17;assert self.y>82,(self.page,label);c.line(48,self.y,564,self.y)
  self.y-=9
 def end(self):self.c.showPage()
 def finish(self):self.c.save()
front=[
('60-Day Total\nMental Makeover',[('An educational workbook for ages 14–24','h'),('12 chapters. 60 days of learning, practice, and reflection. A flexible path toward clearer choices and a kinder conversation with yourself.','p'),('English edition 1.0.0 · October 2026','p'),('Take more time if you need it. Use fictional examples. Keep your responses private. You do not have to become someone else to begin.','p')]),
('Ownership & educational boundaries',[('© 2026 Timeless Empowerment Foundation. All rights reserved. Published/Owned by Timeless Empowerment Foundation, a 501(c)(3) nonprofit. Created/Designed by Thornton H. Taylor (Board Member). Structure Designed by Supreme Development Group (SDG). Distributed by Timeless Innovations LLC.','p'),('This workbook is general education. It does not provide diagnosis, therapy, medical advice, or a promise of recovery. It has not been clinically validated. A participation certificate is not a professional credential.','p'),('You may pause, skip, or use fictional examples. Do not change prescribed treatment because of this workbook. Seek qualified care for health concerns. This resource is not monitored and is not an emergency service. If someone may be in immediate danger, contact local emergency services.','p'),('No payment or donation is collected by the accompanying website. A purchase is not a donation, and this workbook does not issue donation receipts.','p'),('Keep written responses and exported files private. The website starts in temporary session mode; optional browser saving is unencrypted by the workbook and can be lost when browser data is cleared. Device speech uses browser services and is not a prerecorded TEF voice.','p')]),
('A welcome from the program',[('Welcome. You may be curious, hopeful, tired, unsure, or several of these at once. You do not need a perfect starting point. The next sixty lessons offer ideas to examine, examples to consider, and space to practice.','p'),('Use the tools with judgment. A thought exercise cannot fix an unsafe situation, lack of resources, or every health concern. Sometimes the useful next step is asking for practical assistance or qualified support. You do not have to exhaust self-help options before asking.','p'),('Your experience matters more than performing a success story. Some ideas may fit; others may not. You can record uncertainty, choose a neutral example, or leave a field blank. Returning after an interruption is part of learning.','p'),('At Days 30 and 60, look back with curiosity. Ask what you can describe or do more clearly, what still needs support, and what you want to keep practicing. Your worth is not measured by a score or a completed checklist.','p')]),
('How to use your workbook',[('Each daily lesson has an objective, a teaching explanation, a worked example, a visual sequence, guided practice, a knowledge check, and a takeaway. The facing page provides writing room.','p'),('Suggested rhythm: read for about three minutes, consider the example for three minutes, practice for five to ten minutes, and reflect for a few minutes. Adapt the pace. Sixty lessons do not require sixty consecutive calendar days.','p'),('Use a safe, ordinary event or a fictional situation. Personal disclosure is optional. Stop an exercise if it makes you uncomfortable. Ask an appropriate person for help when an issue is outside the scope of a workbook.','p'),('On the website, mark a lesson reviewed after engaging with it in the way you choose. Writing and quiz answers are optional. Review marks are self-reported. Export a backup before changing devices or clearing browser data.','p'),('The PDF is a printable edition with blank writing lines. Website responses are not automatically added to this PDF. Use Print lesson & my notes or Print my journal to create a separate copy of entered writing.','p')]),
('A plain-language learning primer',[('Thought awareness','h'),('A thought can contain a prediction or interpretation rather than an established fact. The workbook practices separating observations, feelings, and chosen actions. It does not ask you to deny real harm or replace every concern with positivity.','p'),('Practice and context','h'),('Repeated practice can make a routine more familiar, but people learn at different rates. Conditions such as access, safety, rest, disability, and support affect what is possible. No fixed “rewiring” deadline or guaranteed change is claimed.','p'),('Flexible habits and grounding','h'),('A simple cue–action–result map helps examine an everyday routine. Optional grounding uses a comfortable external detail to return attention to the present. You can adapt or stop it. No breath holding or closed eyes are required.','p'),('Evidence and limits','h'),('General educational context comes from WHO stress-management guidance and NIMH/NIH self-care resources, linked in the back matter. These references do not establish that this original program is a tested treatment.','p')]),
('Your starting snapshot',[]),('Your 60-day roadmap',[]),('Your flexible learning agreement',[])]
b=Book(OUT/'workbook.pdf','60-Day Total Mental Makeover — Complete Workbook')
